/**
 * The `pom.xml` of a Java view project: Java 17, JUnit 5 and AssertJ for the translated tests
 * (`src/test/java`), and the surefire plugin that runs them. Written next to `src/`, so
 * `mvn test` in the view folder compiles the views and runs the tests.
 */

import * as fs from 'fs';
import * as path from 'path';

export const JAVA_RELEASE = 17;
export const JUNIT_VERSION = '5.11.4';
export const ASSERTJ_VERSION = '3.27.3';
export const SUREFIRE_VERSION = '3.5.2';

export function pomText(basePackage: string): string {
  return `<?xml version="1.0" encoding="UTF-8"?>
<!-- Generated by Pyrite - do not edit. -->
<project xmlns="http://maven.apache.org/POM/4.0.0"
         xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"
         xsi:schemaLocation="http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd">
  <modelVersion>4.0.0</modelVersion>

  <groupId>${basePackage}</groupId>
  <artifactId>${basePackage.replace(/_/g, '-')}</artifactId>
  <version>0.0.0-SNAPSHOT</version>

  <properties>
    <maven.compiler.release>${JAVA_RELEASE}</maven.compiler.release>
    <project.build.sourceEncoding>UTF-8</project.build.sourceEncoding>
    <junit.version>${JUNIT_VERSION}</junit.version>
    <assertj.version>${ASSERTJ_VERSION}</assertj.version>
  </properties>

  <dependencies>
    <dependency>
      <groupId>org.junit.jupiter</groupId>
      <artifactId>junit-jupiter</artifactId>
      <version>\${junit.version}</version>
      <scope>test</scope>
    </dependency>
    <dependency>
      <groupId>org.assertj</groupId>
      <artifactId>assertj-core</artifactId>
      <version>\${assertj.version}</version>
      <scope>test</scope>
    </dependency>
  </dependencies>

  <build>
    <plugins>
      <plugin>
        <groupId>org.apache.maven.plugins</groupId>
        <artifactId>maven-surefire-plugin</artifactId>
        <version>${SUREFIRE_VERSION}</version>
      </plugin>
    </plugins>
  </build>
</project>
`;
}

/** Write `pom.xml` in `outRoot`; a file already up to date is left alone, so watchers see no change. */
export function writeBuildFile(outRoot: string, basePackage: string): void {
  const target = path.join(outRoot, 'pom.xml');
  const content = pomText(basePackage);
  if (fs.existsSync(target) && fs.readFileSync(target, 'utf8') === content) return;
  fs.mkdirSync(outRoot, { recursive: true });
  fs.writeFileSync(target, content, 'utf8');
}
